```python
import sys

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    def nextline():
        nonlocal idx
        while idx < len(data):
            line = data[idx].strip()
            idx += 1
            if line != '':
                return line
        return None

    first = nextline()
    if first is None:
        print('ERR'); return
    try:
        k = int(first)
    except ValueError:
        print('ERR'); return
    if k < 1 or k > 64:
        print('ERR'); return

    prog = []
    for _ in range(k):
        ln = nextline()
        if ln is None:
            print('ERR'); return
        parts = ln.split()
        op = parts[0]
        if op == 'PUSH':
            if len(parts) != 2:
                print('ERR'); return
            try:
                v = int(parts[1])
            except ValueError:
                print('ERR'); return
            prog.append(('PUSH', v))
        elif op in ('POP', 'ADD', 'SUB', 'MUL', 'DUP', 'SWAP', 'PRINT', 'HALT'):
            prog.append((op, None))
        elif op == 'JNZ':
            if len(parts) != 2:
                print('ERR'); return
            try:
                v = int(parts[1])
            except ValueError:
                print('ERR'); return
            prog.append(('JNZ', v))
        else:
            print('ERR'); return

    stack = []
    out = []
    pc = 0
    steps = 0
    LIMIT = 10000

    while True:
        steps += 1
        if steps > LIMIT:
            print('ERR'); return
        if pc < 0 or pc >= len(prog):
            print('ERR'); return
        op, arg = prog[pc]
        if op == 'PUSH':
            stack.append(arg)
            pc += 1
        elif op == 'POP':
            if not stack:
                print('ERR'); return
            stack.pop()
            pc += 1
        elif op == 'DUP':
            if not stack:
                print('ERR'); return
            stack.append(stack[-1])
            pc += 1
        elif op == 'SWAP':
            if len(stack) < 2:
                print('ERR'); return
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == 'ADD':
            if len(stack) < 2:
                print('ERR'); return
            a = stack.pop(); b = stack.pop()
            stack.append(b + a)
            pc += 1
        elif op == 'SUB':
            if len(stack) < 2:
                print('ERR'); return
            a = stack.pop(); b = stack.pop()
            stack.append(b - a)
            pc += 1
        elif op == 'MUL':
            if len(stack) < 2:
                print('ERR'); return
            a = stack.pop(); b = stack.pop()
            stack.append(b * a)
            pc += 1
        elif op == 'PRINT':
            if not stack:
                print('ERR'); return
            out.append(str(stack.pop()))
            pc += 1
        elif op == 'JNZ':
            if not stack:
                print('ERR'); return
            v = stack.pop()
            if v != 0:
                if arg < 0 or arg >= len(prog):
                    print('ERR'); return
                pc = arg
            else:
                pc += 1
        elif op == 'HALT':
            for line in out:
                sys.stdout.write(line + '\n')
            return

main()
```

要点：k 条指令全部读入后进入执行循环；每条指令计 1 步，超 10000 步即 ERR；pc 越过末尾（含执行流落到最后一条之后）判 ERR；JNZ 目标越界判 ERR。
